}
let iMis = 0, iEx = [];
for (const v of blankCases) {
  const L = lodashIsEmpty(v), C = etCompat.isEmpty(v);
  if (L !== C) { iMis++; if (iEx.length<5) iEx.push({v, L, C}); }
}
console.log('isEmpty mismatches (compat):', iMis, iEx);
